package demo.pharma.catalog;
import demo.pharma.common.exception.NotFoundException; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/medicines") @RequiredArgsConstructor public class MedicineDetailController {private final MedicineRepository medicines;record Detail(UUID id,String medicineCode,String name,String genericName,String brandName,UUID manufacturerId,UUID categoryId,String composition,DosageForm dosageForm,String strength,String packSize,String unit,boolean prescriptionRequired,BigDecimal taxPercentage,BigDecimal reorderLevel,String description,RecordStatus status){}@GetMapping("/{id}/detail")@PreAuthorize("hasAuthority('MEDICINE_VIEW')")Detail detail(@PathVariable UUID id){Medicine m=medicines.findById(id).orElseThrow(()->new NotFoundException("Medicine",id));return new Detail(m.getId(),m.getMedicineCode(),m.getName(),m.getGenericName(),m.getBrandName(),m.getManufacturer()==null?null:m.getManufacturer().getId(),m.getCategory()==null?null:m.getCategory().getId(),m.getComposition(),m.getDosageForm(),m.getStrength(),m.getPackSize(),m.getUnit(),m.isPrescriptionRequired(),m.getTaxPercentage(),m.getReorderLevel(),m.getDescription(),m.getStatus());}}
